SELECT CASE WHEN discount_pct >= 0.31 THEN 'HIGH' ELSE 'LOW' END AS discount_pct_tier, SIZE(COLLECT_SET(channel)) AS num_channels, APPROX_PERCENTILE(discount_pct, 0.9) AS discount_pct_p90, COUNT(CASE WHEN promo_code = 'SPRING10' THEN 1 END) AS spring10_count, SORT_ARRAY(COLLECT_SET(channel)) AS channel_list FROM promotions GROUP BY CASE WHEN discount_pct >= 0.31 THEN 'HIGH' ELSE 'LOW' END HAVING num_channels > 1;
